// 64x64 void-and-cluster blue-noise threshold tile (generated by us, Ulichney 1993; no third-party data).
export const BLUE_N = 64;
export const BLUE_B64 = '';
export function blueNoise(): Uint8Array { const s = atob(BLUE_B64); const a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; }
